    "Показывать маленькую иконку сборки": "Show the small instance icon",
    "Для Modrinth и CurseForge используется публичная иконка проекта, если она совпадает с иконкой сборки. Встроенные значки и буквы работают без загрузки файлов.": "For Modrinth and CurseForge, the public project icon is used if it matches the instance icon. Built-in icons and letters work without uploading files.",
    "Свои картинки": "Your pictures",
    "Разрешить публикацию локальных иконок для Discord": "Allow publishing local icons for Discord",
    "По умолчанию выключено. При включении выбранная иконка уменьшится и отправится на публичный сторонний сервис tmpfile.link: её сможет открыть любой, у кого есть ссылка. Сервис заявляет удаление через 7 дней; досрочно удалить файл нельзя, а Discord может кэшировать его дольше. Отключение переключателя не удаляет уже отправленные файлы. Без разрешения вместо своей картинки показывается буква сборки.": "Off by default. When enabled, the selected icon is resized and uploaded to the public third-party service tmpfile.link. Anyone with the link can view it. The service says it deletes files after 7 days; files cannot be deleted earlier, and Discord may cache them for longer. Turning this off does not delete files already uploaded. Without permission, the instance’s initial is shown instead of your image.",
