    "## Что внутри - оптимизация рендера и загрузки чанков - набор шейдеров и ресурспаков - готовые настройки графики ![скриншот](demo.png) Подходит для слабых и средних ПК: FPS растёт, картинка не страдает.": "## Што ўсярэдзіне - аптымізацыя рэндэру і загрузкі чанков - набор шэйдараў і рэсурспакаў - гатовыя налады графікі ![скрыншот](demo.png) Падыходзіць для слабых і сярэдніх ПК: FPS расце, малюнак не пакутуе.",
