    "Что нового в 0.2.0: • Автообновление через GitHub Releases • Кнопка «Обновить и перезапустить» прямо в лаунчере • Исправлена установка модов с обязательными зависимостями • Ускорена проверка файлов после первого запуска": "Што новага ў 0.2.0: • Аўтаабнаўленне праз GitHub Releases • Кнопка «Абнавіць і перазапусціць» прама ў лаўнчэры • Выпраўлена ўстаноўка модаў з абавязковымі залежнасцямі • Паскорана праверка файлаў пасля першага запуску",
    "Исправлена установка модов с обязательными зависимостями": "Выпраўлена ўстаноўка модаў з абавязковымі залежнасцямі",
    "Ускорена проверка файлов после первого запуска": "Паскорана праверка файлаў пасля першага запуску",
