    "Для Modrinth и CurseForge используется публичная иконка проекта, если она совпадает с иконкой сборки. Встроенные значки и буквы работают без загрузки файлов.": "Для Modrinth і CurseForge выкарыстоўваецца публічны значок праекта, калі ён супадае са значком зборкі. Убудаваныя значкі і літары працуюць без загрузкі файлаў.",
    "Свои картинки": "Свае карцінкі",
    "Разрешить публикацию локальных иконок для Discord": "Дазволіць публікацыю лакальных абразкоў для Discord",
    "По умолчанию выключено. При включении выбранная иконка уменьшится и отправится на публичный сторонний сервис tmpfile.link: её сможет открыть любой, у кого есть ссылка. Сервис заявляет удаление через 7 дней; досрочно удалить файл нельзя, а Discord может кэшировать его дольше. Отключение переключателя не удаляет уже отправленные файлы. Без разрешения вместо своей картинки показывается буква сборки.": "Па змаўчанні выключана. Пры ўключэнні выбраны значок будзе паменшаны і адпраўлены на публічны старонні сэрвіс tmpfile.link: яго зможа адкрыць кожны, хто мае спасылку. Сэрвіс заяўляе, што выдаляе файлы праз 7 дзён; выдаліць іх раней нельга, а Discord можа захоўваць іх у кэшы даўжэй. Выключэнне перамыкача не выдаляе ўжо адпраўленыя файлы. Без дазволу замест сваёй выявы паказваецца першая літара назвы зборкі.",
