    "эта сборка уже запущена или подготавливается": "гэтая зборка ўжо запушчана або падрыхтоўваецца",
    "идёт установка из диагностики; дождись её завершения": "ідзе ўстаноўка з дыягностыкі; чакай яе завяршэння",
    "сначала останови все окна, использующие эту папку игры, и дождись окончания подготовки сборок": "спачатку спыні ўсе вокны, якія выкарыстоўваюць гэтую тэчку гульні, і чакай заканчэння падрыхтоўкі зборак",
    "сборка уже изменяется; дождись завершения операции": "зборка ўжо змяняецца; чакай завяршэння аперацыі",
    "неизвестный язык интерфейса": "невядомая мова інтэрфейсу",
    "не удалось сохранить иконку: {0}": "не атрымалася захаваць абразок: {0}",
    "не удалось сохранить иконку: {0}; не удалось восстановить значок окна: {1}": "не ўдалося захаваць абразок: {0}; не ўдалося аднавіць значок акна: {1}",
    "неизвестная иконка лаунчера": "невядомая абразок лаўнчэра",
    "окно лаунчера недоступно": "акно лаўнчара недаступна",
    "не удалось обновить последнюю сборку в настройках: {0}": "не атрымалася абнавіць апошнюю зборку ў наладах: {0}",
    "готовим профиль версии": "рыхтуем профіль версіі",
    "[omnispec] профиль загрузчика не установлен: {0}": "[omnispec] профіль загрузніка не ўсталяваны: {0}",
    "новая сборка с модом создаётся только в отдельной папке лаунчера": "новая зборка з модам ствараецца толькі ў асобнай тэчцы лаўнчара",
    "для мода нужен поддерживаемый загрузчик": "для мода патрэбен які падтрымліваецца загрузнік",
    "неизвестный каталог модов": "невядомы каталог модаў",
    "выбранный файл не принадлежит этому моду": "абраны файл не належыць гэтаму моду",
    "у выбранной версии нет файла": "у абранай версіі няма файла",
    "эта версия Minecraft отсутствует в официальном манифесте": "гэтая версія Minecraft адсутнічае ў афіцыйным маніфесце",
    "эта версия загрузчика недоступна для выбранного Minecraft": "гэтая версія загрузніка недаступная для абранага Minecraft",
    "дождись окончания установки из диагностики": "чакай заканчэння ўстаноўкі з дыягностыкі",
