    "Не удалось подписаться на сообщения игры. Автоматическая проверка лога работать не будет; проверь лог в папке сборки.": "Ойын хабарларына жазылу мүмкін болмады. Журналды автоматты тексеру жұмыс істемейді; құрастыру қалтасындағы журналды тексеріңіз.",
    "Пока нет данных": "Әзірге деректер жоқ",
    "Запусти эту сборку: здесь появятся подсказки, если в выводе найдутся известные признаки проблем.": "Бұл құрастыруды іске қосыңыз және шығыста ақаулардың белгілі белгілері болса, осы жерден кеңестерді көресіз.",
    "Подготавливаем запуск": "Ұшыруды дайындау",
    "Проверяем ошибки подготовки и будем разбирать новые строки лога по мере их появления.": "Біз дайындық қателерін тексереміз және олар пайда болған кезде жаңа журнал жолдарын талдаймыз.",
    "Не удалось подписаться на сообщения игры. Автоматическая проверка и состояние завершения могут быть неполными; проверь лог в папке сборки.": "Ойын хабарларына жазылу мүмкін болмады. Автоматты тексеру және аяқтау күйі толық емес болуы мүмкін; құрастыру қалтасындағы журналды тексеріңіз.",
    "Есть сигналы в логе": "Журналда сигналдар бар",
    "Игра ещё работает. Эти сообщения не обязательно означают, что запуск завершится с ошибкой.": "Ойын әлі жалғасуда. Бұл хабарлар іске қосу сәтсіз болады дегенді білдірмейді.",
    "Пока ничего подозрительного": "Әлі күдікті ештеңе жоқ",
    "Процесс запущен. Продолжаем проверять новые строки; не все проблемы можно определить автоматически.": "Процесс басталды. Біз жаңа жолдарды тексеруді жалғастырамыз; Барлық ақауларды автоматты түрде анықтау мүмкін емес.",
    "Подготовка отменена": "Дайындық тоқтатылды",
    "Загрузка была отменена пользователем. Можно запустить сборку снова.": "Жүктеп алуды пайдаланушы тоқтатты. Құрылымды қайта іске қосуға болады.",
    "Игра остановлена пользователем": "Ойынды пайдаланушы тоқтатты",
    "До остановки в логе встретились сообщения ниже; они не обязательно означают сбой.": "Аялдама алдында журналда келесі хабарламалар табылды; олар міндетті түрде сәтсіздікті білдірмейді.",
    "Ручная остановка не считается ошибкой запуска.": "Қолмен тоқтату іске қосу қатесі болып саналмайды.",
    "Не удалось подготовить запуск": "Іске қосуды дайындау мүмкін болмады",
    "Ниже — подсказки по распознанным сообщениям. Проверь полную ошибку, если они не помогут.": "Төменде танылған хабарлар бойынша кеңестер берілген. Егер олар көмектеспесе, толық қатені тексеріңіз.",
    "Известную причину определить не удалось. Посмотри сообщение запуска и приложи его к обращению.": "Белгілі себепті анықтау мүмкін болмады. Іске қосу хабарламасын қараңыз және оны сұрауыңызға қосыңыз.",
    "Игра завершилась с кодом 0": "Ойын 0 кодымен аяқталды",
    "В логе были сообщения ниже. Они могут быть предупреждениями и не обязательно указывают на сбой.": "Төменде журналда хабарламалар болды. Олар ескерту болуы мүмкін және міндетті түрде сәтсіздікті көрсетпейді.",
    "Известные ошибки не найдены": "Белгілі қателер табылмады",
    "Игра завершилась с кодом 0. Это не гарантирует, что другие проблемы отсутствуют.": "Ойын 0 кодымен аяқталды. Бұл басқа мәселелердің жоқтығына кепілдік бермейді.",
    "Код завершения недоступен.": "Шығу коды қолжетімді емес.",
