    "{0} Сам по себе код не объясняет причину; ниже — признаки, найденные в логе.": "{0} Кодтың өзі себебін түсіндірмейді; Төменде журналда табылған белгілер бар.",
    "Причину определить не удалось": "Себебін анықтау мүмкін болмады",
    "{0} Сам по себе код не объясняет причину. Понадобится полный лог или краш-отчёт.": "{0} Кодтың өзі себебін түсіндірмейді. Сізге толық журнал немесе қате туралы есеп қажет.",
    "Помощь при запуске": "Іске қосу бойынша көмек",
    "Ошибки сборки": "Қателерді құрастыру",
    "Разбираем известные проблемы локально. Файлы не меняются без твоего действия; для установки подходящей версии используется каталог Modrinth.": "Біз жергілікті жерде белгілі проблемаларды қарастырамыз. Файлдар сіздің әрекетіңізсіз өзгермейді; Modrinth каталогы сәйкес нұсқаны орнату үшін пайдаланылады.",
    "Открыть консоль": "Ашық консоль",
    "Настройки изменились после этого запуска: тогда {0}, сейчас {1}.": "Осы іске қосылғаннан кейін параметрлер өзгерді: содан кейін {0}, енді {1}.",
    "Запусти сборку снова и проверь новую диагностику: старое требование может больше не относиться к ней.": "Құрылымды қайта іске қосыңыз және жаңа диагностиканы тексеріңіз: ескі талап енді оған қолданылмауы мүмкін.",
    "Не заменяй и не удаляй файлы по старой ошибке; при необходимости проверь полный лог.": "Ескі қатеге байланысты файлдарды ауыстырмаңыз немесе жоймаңыз; Қажет болса, толық журналды тексеріңіз.",
    "Это не последняя попытка или её настройки неизвестны. Запусти сборку снова и проверь новую диагностику.": "Бұл соңғы әрекет емес немесе оның параметрлері белгісіз. Құрылымды қайта іске қосыңыз және жаңа диагностиканы тексеріңіз.",
    "Состав модов уже изменён. Запусти сборку снова и проверь актуальные сообщения перед следующей установкой.": "Модтардың құрамы қазірдің өзінде өзгертілген. Құрылымды қайта іске қосыңыз және келесі орнату алдында ағымдағы хабарларды тексеріңіз.",
    "Сейчас выбрано {0}. Сообщение относится к зависимости Fabric; не устанавливай её вслепую.": "Қазіргі таңда {0}. Хабар Fabric тәуелділігіне сілтеме жасайды; Оны көзсіз орнатпаңыз.",
    "Проверь, что выбрана нужная сборка и загрузчик, затем снова запусти игру и изучи полный лог.": "Дұрыс құрастыру және жүктеуші таңдалғанын тексеріңіз, содан кейін ойынды қайта іске қосыңыз және толық журналды тексеріңіз.",
    "В логе встретились несколько требований к версии, которые нельзя надёжно сравнить автоматически.": "Журналда автоматты түрде сенімді түрде салыстыруға келмейтін бірнеше нұсқа талаптары бар.",
    "Проверь полный лог и подбери версию во встроенном разделе «Моды», не заменяя файлы вслепую.": "Толық журналды тексеріңіз және файлдарды соқыр ауыстырмай кірістірілген «Модтар» бөлімінде нұсқаны таңдаңыз.",
    "Настройки этой попытки: {0}.": "Бұл әрекеттің параметрлері {0} болып табылады.",
    "Останови все окна этой сборки и сохрани резервную копию важных миров и модов.": "Осы құрылымның барлық терезелерін тоқтатып, маңызды дүниелер мен модтардың сақтық көшірмесін сақтаңыз.",
    "Нажми кнопку установки: лаунчер сначала проверит существующие .jar и выключенные файлы .disabled. Не добавляй вторую копию.": "Орнату түймесін басыңыз: іске қосу құралы алдымен бар .jar және өшірілген .disabled файлдарын тексереді. Екінші көшірмені қоспаңыз.",
    ", версия не ниже {0}": ", нұсқасы {0} төмен емес",
    "Лаунчер подберёт файл для Minecraft {0} и Fabric{1}; проверит требования fabric.mod.json к Fabric Loader и Java последнего запуска, а также SHA-512.": "Іске қосу құралы Minecraft {0} және Fabric{1} үшін файлды таңдайды; Fabric Loader және соңғы іске қосылған Java, сондай-ақ SHA-512 үшін fabric.mod.json талаптарын тексереді.",
    "Если найденный файл нужно заменить, сначала появится подтверждение; старая версия сохранится в резервной копии.": "Табылған файлды ауыстыру қажет болса, алдымен растау пайда болады; ескі нұсқасы сақтық көшірмеде сақталады.",
    "Запусти сборку снова. Могут потребоваться и другие зависимости: их нужно проверить по новому логу.": "Құрылымды қайта іске қосыңыз. Басқа тәуелділіктер де қажет болуы мүмкін: оларды жаңа журнал арқылы тексеру керек.",
    "Останови игру и проверь актуальную попытку запуска": "Ойынды тоқтатып, ағымдағы іске қосу әрекетін тексеріңіз",
    "Проверяем файлы и подбираем совместимую версию…": "Біз файлдарды тексеріп, үйлесімді нұсқаны таңдаймыз...",
