    "Уже установлен и включён {0} ({1}). Вторую копию не добавляли; проверь новый лог и остальные зависимости.": "{0} ({1}) орнатылған және қосылған. Екінші көшірме қосылмаған; жаңа журналды және басқа тәуелділіктерді тексеріңіз.",
