    "Изображения": "Суреттер",
    "Большая картинка — логотип OmniSpec. Маленькая — значок выбранной сборки.": "Үлкен сурет — OmniSpec логотипі. Кішкентай сурет — таңдалған жинақтың белгішесі.",
    "Показывать маленькую иконку сборки": "Жинақтың шағын белгішесін көрсету",
    "Для Modrinth и CurseForge используется публичная иконка проекта, если она совпадает с иконкой сборки. Встроенные значки и буквы работают без загрузки файлов.": "Modrinth және CurseForge жобасының жалпыға қолжетімді белгішесі жинақ белгішесіне сәйкес келсе пайдаланылады. Кірістірілген белгішелер мен әріптер файлдарды жібермей жұмыс істейді.",
    "Свои картинки": "Сіздің суреттеріңіз",
    "Разрешить публикацию локальных иконок для Discord": "Discord үшін жергілікті белгішелерді жариялауға рұқсат беріңіз",
    "По умолчанию выключено. При включении выбранная иконка уменьшится и отправится на публичный сторонний сервис tmpfile.link: её сможет открыть любой, у кого есть ссылка. Сервис заявляет удаление через 7 дней; досрочно удалить файл нельзя, а Discord может кэшировать его дольше. Отключение переключателя не удаляет уже отправленные файлы. Без разрешения вместо своей картинки показывается буква сборки.": "Әдепкіде өшірулі. Қосылғанда таңдалған белгіше кішірейтіліп, жалпыға қолжетімді бөгде tmpfile.link қызметіне жіберіледі: сілтемесі бар кез келген адам оны аша алады. Қызмет файлдарды 7 күннен кейін жоятынын мәлімдейді; оларды ертерек жою мүмкін емес, ал Discord оларды кэште ұзағырақ сақтауы мүмкін. Ауыстырғышты өшіру бұрын жіберілген файлдарды жоймайды. Рұқсат берілмесе, суреттің орнына жинақ атауының бірінші әрпі көрсетіледі.",
