    "Большая картинка — логотип OmniSpec. Маленькая — значок выбранной сборки.": "Велике зображення — логотип OmniSpec. Маленьке — значок вибраної збірки.",
    "Показывать маленькую иконку сборки": "Показувати маленький значок збірки",
    "Для Modrinth и CurseForge используется публичная иконка проекта, если она совпадает с иконкой сборки. Встроенные значки и буквы работают без загрузки файлов.": "Для Modrinth і CurseForge використовується публічний значок проєкту, якщо він збігається зі значком збірки. Вбудовані значки та літери працюють без надсилання файлів.",
    "Свои картинки": "Свої картинки",
    "Разрешить публикацию локальных иконок для Discord": "Дозволити публікацію локальних іконок для Discord",
    "По умолчанию выключено. При включении выбранная иконка уменьшится и отправится на публичный сторонний сервис tmpfile.link: её сможет открыть любой, у кого есть ссылка. Сервис заявляет удаление через 7 дней; досрочно удалить файл нельзя, а Discord может кэшировать его дольше. Отключение переключателя не удаляет уже отправленные файлы. Без разрешения вместо своей картинки показывается буква сборки.": "За замовчуванням вимкнено. Якщо ввімкнути, вибраний значок буде зменшено й надіслано до публічного стороннього сервісу tmpfile.link: його зможе відкрити кожен, хто має посилання. Сервіс заявляє, що видаляє файли через 7 днів; видалити їх раніше не можна, а Discord може кешувати їх довше. Вимкнення перемикача не видаляє вже надіслані файли. Без дозволу замість власного зображення показується перша літера назви збірки.",
