    "Проверь папку mods: Fabric API может уже находиться там или быть выключен с окончанием .disabled. Не добавляй вторую копию.": "Перевірте папку mods: Fabric API може вже знаходитися там або бути вимкнений з закінченням .disabled. Чи не додай другу копію.",
    "Подбери совместимую версию в лаунчере и проверь остальные требования лога.": "Підбери сумісну версію в лаунчері та перевір інші вимоги лога.",
